// 实现手写惯性旋转、滚轮缩放、键盘与双击复位。
import{clamp}from'../utils/lerp.js';
export function bindControls(canvas,state){let pointer=null,lastX=0,lastY=0;canvas.addEventListener('pointerdown',event=>{pointer=event.pointerId;lastX=event.clientX;lastY=event.clientY;canvas.setPointerCapture(pointer);state.dragging=true;});canvas.addEventListener('pointermove',event=>{if(pointer!==event.pointerId)return;state.yaw+=(event.clientX-lastX)*.008;state.pitch=clamp(state.pitch+(event.clientY-lastY)*.004,-.45,.45);lastX=event.clientX;lastY=event.clientY;});const end=()=>{pointer=null;state.dragging=false;};canvas.addEventListener('pointerup',end);canvas.addEventListener('pointercancel',end);canvas.addEventListener('lostpointercapture',end);canvas.addEventListener('wheel',event=>{event.preventDefault();state.zoom=clamp(state.zoom+event.deltaY*.002,3.4,7);},{passive:false});canvas.addEventListener('dblclick',()=>state.reset());canvas.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home'].includes(event.key))return;event.preventDefault();if(event.key==='ArrowLeft')state.yaw-=.25;if(event.key==='ArrowRight')state.yaw+=.25;if(event.key==='ArrowUp')state.zoom=clamp(state.zoom-.2,3.4,7);if(event.key==='ArrowDown')state.zoom=clamp(state.zoom+.2,3.4,7);if(event.key==='Home')state.reset();});}
